from . import point as pt

# Rédigé par une IA, non relu par un locuteur natif : à vérifier avec une source fiable.
POINTS = [
pt('A1', 'ordre', ("L'ordre des mots : le prédicat d'abord",
 "Le tagalog place d'ordinaire le prédicat avant le sujet : Maganda ang bahay (beau + le maison = la maison est belle). Le verbe vient avant son sujet : Kumain ako (a mangé + moi).\nLes marqueurs ang (sujet défini), ng (non défini, possessif, agent) et sa (lieu, direction, destinataire) précèdent le nom. Pour les personnes : si (sujet), ni (de), kay (à).\nPas de genre, pas de verbe « être » au présent."),
 ('Word order: predicate first',
 "Tagalog usually puts the predicate before the subject: Maganda ang bahay (beautiful + the house = the house is beautiful). The verb precedes its subject: Kumain ako (ate + I).\nThe markers ang (definite subject), ng (indefinite, possessor, agent) and sa (place, direction, recipient) come before the noun. For people: si (subject), ni (of), kay (to).\nNo gender and no verb “to be” in the present."),
 [("Maganda ang bahay.", "La maison est belle.", "The house is beautiful.", ""), ("Kumain ako ng mansanas.", "J'ai mangé une pomme.", "I ate an apple.", "")],
 r"\b(ang|ng|sa|si|ni|kay)\b", ['ang', 'ng', 'sa', 'si', 'ni', 'kay']),
pt('A1', 'pronoms', ("Les pronoms personnels",
 "Trois séries : sujet (ako, ikaw / ka, siya, kami / tayo, kayo, sila), génitif (ko, mo, niya, namin / natin, ninyo, nila) et oblique (akin, iyo, kanya, amin / atin, inyo, kanila).\nDeux « nous » : tayo inclut l'interlocuteur, kami l'exclut.\nLes pronoms courts (ko, mo, ka, ako…) se placent juste après le premier mot de la phrase : Kumain ka na ba?"),
 ('Personal pronouns',
 "Three sets: subject (ako, ikaw / ka, siya, kami / tayo, kayo, sila), genitive (ko, mo, niya, namin / natin, ninyo, nila) and oblique (akin, iyo, kanya, amin / atin, inyo, kanila).\nTwo kinds of “we”: tayo includes the listener, kami excludes them.\nShort pronouns (ko, mo, ka, ako…) go right after the first word of the sentence: Kumain ka na ba?"),
 [("Mahal kita.", "Je t'aime.", "I love you.", ""), ("Ano ang pangalan mo?", "Comment t'appelles-tu ?", "What is your name?", "")],
 r"\b(ako|ikaw|ka|siya|kami|tayo|kayo|sila|ko|mo|niya|namin|natin|nila)\b", ['ako', 'ikaw', 'siya', 'kami', 'tayo', 'sila']),
pt('A1', 'demonstratifs', ("Ito, iyan, iyon ; dito, diyan, doon",
 "Ceci (près de moi) : ito. Cela (près de toi) : iyan. Là-bas : iyon. Avec un nom : itong bahay, iyang bahay, iyong bahay.\nLieux : dito (ici), diyan (là, près de toi), doon (là-bas).\nExistence : may / mayroon (il y a, avoir) ; wala (il n'y a pas) : May pera ako. Wala siya rito."),
 ('Ito, iyan, iyon; dito, diyan, doon',
 "This (near me): ito. That (near you): iyan. Over there: iyon. With a noun: itong bahay, iyang bahay, iyong bahay.\nPlaces: dito (here), diyan (there, near you), doon (over there).\nExistence: may / mayroon (there is, have); wala (there isn't): May pera ako. Wala siya rito."),
 [("Ano ito?", "Qu'est-ce que c'est ?", "What is this?", ""), ("Nasa bahay siya.", "Il est à la maison.", "He is at home.", "")],
 r"\b(ito|iyan|iyon|dito|diyan|doon|may|wala)\b", ['ito', 'iyan', 'iyon', 'dito', 'diyan', 'doon']),
pt('A1', 'negation-questions', ("Négation et questions",
 "Négation : hindi (pour verbes et adjectifs : Hindi ako pagod), wala (absence), huwag (ordre négatif : Huwag kang umalis).\nQuestion fermée : ba, placé après le premier mot (Kumain ka na ba?). Mots interrogatifs : ano, sino, saan, kailan, paano, bakit, ilan, magkano (combien d'argent)."),
 ('Negation and questions',
 "Negative: hindi (verbs and adjectives: Hindi ako pagod), wala (absence), huwag (negative command: Huwag kang umalis).\nYes/no question: ba, after the first word (Kumain ka na ba?). Question words: ano, sino, saan, kailan, paano, bakit, ilan, magkano (how much money)."),
 [("Saan ka pupunta?", "Où vas-tu ?", "Where are you going?", ""), ("Hindi ko alam.", "Je ne sais pas.", "I don't know.", "")],
 r"^(Ano|Sino|Saan|Kailan|Paano|Bakit|Ilan|Magkano)\b", ['Ano', 'Sino', 'Saan', 'Kailan', 'Paano', 'Bakit']),
pt('A2', 'aspects', ("Les aspects du verbe",
 "Le verbe ne se conjugue pas selon le temps mais selon l'aspect. Trois formes : accompli (terminé), inaccompli (en cours ou habituel), contemplatif (à venir).\nVerbes en -um- : sulat → sumulat (écrivit), sumusulat (écrit / écrira à l'instant), susulat (écrira). Verbes en mag- : magluto → nagluto, nagluluto, magluluto.\nLe radical redoublé la première syllabe pour l'inaccompli et le contemplatif. Infinitif : sumulat, magluto."),
 ('Verb aspects',
 "Verbs are not conjugated for tense but for aspect. Three forms: completed, incompleted (ongoing or habitual), contemplated (to come).\n-um- verbs: sulat → sumulat (wrote), sumusulat (is writing), susulat (will write). mag- verbs: magluto → nagluto, nagluluto, magluluto.\nThe first syllable of the stem is repeated for the incompleted and contemplated forms. Infinitive: sumulat, magluto."),
 [("Kumain ako kahapon.", "J'ai mangé hier.", "I ate yesterday.", ""), ("Kakain ako mamaya.", "Je mangerai tout à l'heure.", "I will eat later.", "")],
 r"\b(kumain|kakain|kumakain|nagluto|magluluto|nagluluto|pumunta|pupunta|pumupunta)\b", None),
pt('A2', 'liaisons', ("Le lien « na / -ng » et « at / pero / kasi »",
 "Entre un adjectif et son nom, on met la ligature na (après consonne) ou -ng (après voyelle, collée au mot, et -ng après n) : magandang bahay, mabait na bata.\nConjonctions : at (et), o (ou), pero / ngunit (mais), kasi / dahil (parce que), kaya (donc), kung (si), habang (pendant que), kapag (quand, si habituel).\nAdverbes d'aspect : na (déjà), pa (encore), lang (seulement), din / rin (aussi)."),
 ('The ligature na / -ng and linking words',
 "Between an adjective and its noun a ligature is used: na (after a consonant) or -ng (after a vowel, attached to the word; -ng after n): magandang bahay, mabait na bata.\nConjunctions: at (and), o (or), pero / ngunit (but), kasi / dahil (because), kaya (so), kung (if), habang (while), kapag (when, if habitual).\nAspect adverbs: na (already), pa (still), lang (only), din / rin (also)."),
 [("Gusto ko ng kape pero wala akong pera.", "Je voudrais du café mais je n'ai pas d'argent.", "I want coffee but I have no money.", "")],
 r"\b(at|o|pero|kasi|dahil|kaya|kung|habang|kapag)\b", ['at', 'o', 'pero', 'kasi', 'dahil', 'kaya']),
pt('B1', 'focus', ("Le système du focus",
 "Le verbe varie selon le rôle du mot marqué par ang. Focus acteur (-um-, mag-) : Kumain ang bata ng isda (l'enfant a mangé du poisson). Focus objet (-in, -an) : Kinain ng bata ang isda (le poisson, l'enfant l'a mangé). Focus destination (-an, i-) : Sinulatan ko si Ana. Focus instrument/bénéficiaire (i-) : Isinulat ko ang liham.\nChoisir le focus, c'est choisir ce dont on parle."),
 ('The focus system',
 "The verb changes according to the role of the ang-marked noun. Actor focus (-um-, mag-): Kumain ang bata ng isda (the child ate fish). Object focus (-in, -an): Kinain ng bata ang isda (the fish, the child ate it). Goal / location focus (-an, i-): Sinulatan ko si Ana. Instrument / beneficiary focus (i-): Isinulat ko ang liham.\nChoosing the focus means choosing what is being talked about."),
 [("Binili ko ang libro.", "J'ai acheté le livre.", "I bought the book.", "")],
 r"\b(binili|kinain|isinulat|sinulatan|ginawa|nakita|kinuha)\b", None),
]

POINTS.insert(0, pt('A1', 'pagbigkas', ("Prononciation",
 "Le tagalog se lit comme il s'écrit. Voyelles : a, e, i, o, u (e et i, o et u se confondent souvent).\n« ng » est un seul son, celui de l'anglais « singer », même en début de mot (ngayon, ngipin). « mga » (pluriel) se lit « ma-nga ». Le mot « ng » se lit « nang ».\nLe coup de glotte n'est pas noté et l'accent tonique change le sens : bata (enfant), batà (endurer) ; baka (vache), bakâ (peut-être). Les dictionnaires le marquent par des accents.\nLes mots d'origine espagnole ou anglaise gardent souvent leur forme (kotse, kompyuter)."),
 ('Pronunciation',
 "Tagalog is read as it is written. Vowels: a, e, i, o, u (e and i, o and u often merge).\n“ng” is a single sound, as in English “singer”, even at the start of a word (ngayon, ngipin). “mga” (plural marker) is read “ma-nga”. The word “ng” is read “nang”.\nThe glottal stop is not written and stress changes the meaning: bata (child), batà (to endure); baka (cow), bakâ (maybe). Dictionaries mark it with accents.\nWords from Spanish or English often keep their shape (kotse, kompyuter)."),
 [("Magandang umaga po.", "Bonjour (le matin).", "Good morning.", ""), ("Nasaan ang mga bata?", "Où sont les enfants ?", "Where are the children?", "")]))

POINTS += [
pt('A1', 'magalang', ("La politesse : po et opo",
 "« po » (ou « ho ») ajouté après le premier mot rend la phrase polie envers un aîné, un inconnu ou un client : Salamat po. Magandang umaga po. Ano po ang pangalan ninyo?\n« Opo » = oui (poli), « hindi po » = non (poli). On vouvoie avec kayo / ninyo au lieu de ikaw / mo.\nPour s'adresser aux gens : Kuya (grand frère), Ate (grande sœur), Tito / Tita (oncle / tante), Lolo / Lola (grand-père / grand-mère), même sans lien de parenté."),
 ('Politeness: po and opo',
 "“po” (or “ho”) after the first word makes a sentence polite towards an elder, a stranger or a customer: Salamat po. Magandang umaga po. Ano po ang pangalan ninyo?\n“Opo” = yes (polite), “hindi po” = no (polite). Use kayo / ninyo instead of ikaw / mo for respect.\nTerms of address: Kuya (big brother), Ate (big sister), Tito / Tita (uncle / aunt), Lolo / Lola (grandpa / grandma), even with no family tie."),
 [("Salamat po.", "Merci (poli).", "Thank you (polite).", ""), ("Opo, naiintindihan ko po.", "Oui, je comprends.", "Yes, I understand.", "")],
 r"\b(po|opo)\b", ['po', 'opo', 'ba', 'na']),
pt('A1', 'lieu', ("Où ? nasa, nasaan, saan, taga-",
 "« nasa » + lieu : se trouver à (Nasa bahay si Ana). « Nasaan » demande où se trouve quelqu'un ou quelque chose (Nasaan ang banyo?). « Saan » demande où se passe une action (Saan ka nakatira? — Sa Maynila).\nOrigine : taga- (Taga-saan ka? — Taga-Cebu ako). Direction et lieu d'action : sa (Pupunta ako sa palengke)."),
 ('Where? nasa, nasaan, saan, taga-',
 "“nasa” + place: to be at (Nasa bahay si Ana). “Nasaan” asks where someone or something is (Nasaan ang banyo?). “Saan” asks where an action happens (Saan ka nakatira? — Sa Maynila).\nOrigin: taga- (Taga-saan ka? — Taga-Cebu ako). Direction and place of action: sa (Pupunta ako sa palengke)."),
 [("Nasaan ang banyo?", "Où sont les toilettes ?", "Where is the toilet?", ""), ("Saan ka nakatira?", "Où habites-tu ?", "Where do you live?", "")],
 r"\b(nasa|nasaan|saan)\b", ['nasa', 'nasaan', 'saan', 'sa']),
pt('A1', 'bilang', ("Les nombres",
 "Nombres tagalogs : isa, dalawa, tatlo, apat, lima, anim, pito, walo, siyam, sampu ; labing-isa (11), dalawampu (20), isang daan (100).\nDevant un nom, la ligature -ng ou na s'ajoute : isang libro, dalawang tao, apat na bata.\nPour l'heure et souvent pour les prix, on emploie les nombres espagnols : alas-tres (trois heures), singkuwenta pesos.\nCombien ? Ilan (nombre) ; Magkano (prix) : Magkano ito?"),
 ('Numbers',
 "Tagalog numbers: isa, dalawa, tatlo, apat, lima, anim, pito, walo, siyam, sampu; labing-isa (11), dalawampu (20), isang daan (100).\nBefore a noun the linker -ng or na is added: isang libro, dalawang tao, apat na bata.\nTime and often prices use Spanish numbers: alas-tres (three o'clock), singkuwenta pesos.\nHow many? Ilan (number); Magkano (price): Magkano ito?"),
 [("May dalawang anak ako.", "J'ai deux enfants.", "I have two children.", ""), ("Magkano ito?", "Combien ça coûte ?", "How much is this?", "")],
 r"\b(isa|isang|dalawa|dalawang|tatlo|tatlong|apat|lima|limang|anim|sampu)\b", None),
pt('A2', 'pang-uri', ("Les adjectifs et la comparaison",
 "La plupart des adjectifs se forment avec ma- + racine : ganda → maganda (beau), laki → malaki (grand), init → mainit (chaud).\nIntensité : napaka- (napakaganda, très beau), sobrang + adjectif (sobrang init), ou Ang + racine en exclamation (Ang ganda!).\nComparatif : mas + adjectif + kaysa (sa) : Mas malaki ito kaysa roon. Superlatif : pinaka- (pinakamaganda). Égalité : kasing- (kasinglaki ng bahay namin)."),
 ('Adjectives and comparison',
 "Most adjectives are ma- + root: ganda → maganda (beautiful), laki → malaki (big), init → mainit (hot).\nIntensity: napaka- (napakaganda, very beautiful), sobrang + adjective (sobrang init), or Ang + root as an exclamation (Ang ganda!).\nComparative: mas + adjective + kaysa (sa): Mas malaki ito kaysa roon. Superlative: pinaka- (pinakamaganda). Equality: kasing- (kasinglaki ng bahay namin)."),
 [("Mas mainit ngayon kaysa kahapon.", "Il fait plus chaud aujourd'hui qu'hier.", "It is hotter today than yesterday.", ""), ("Ang ganda ng dagat!", "Que la mer est belle !", "The sea is so beautiful!", "")],
 r"\b(mas|kaysa|pinaka\w*|napaka\w*|sobrang)\b", None),
pt('A2', 'pag-aari', ("Avoir et posséder",
 "Avoir, il y a : may + nom (May kotse ako = j'ai une voiture), ou mayroon / meron + ligature (Mayroon akong kotse). Négation : wala (Wala akong pera).\nÀ qui ? Kanino : Kanino ang bag na ito? — Akin (à moi) / Sa akin.\nPossessifs placés après le nom : ang libro ko (mon livre), ang bahay nila ; ou devant avec la ligature : ang aking libro, ang kanilang bahay."),
 ('Having and owning',
 "To have, there is: may + noun (May kotse ako = I have a car), or mayroon / meron + linker (Mayroon akong kotse). Negative: wala (Wala akong pera).\nWhose? Kanino: Kanino ang bag na ito? — Akin (mine) / Sa akin.\nPossessives after the noun: ang libro ko (my book), ang bahay nila; or before it with the linker: ang aking libro, ang kanilang bahay."),
 [("Wala akong pera.", "Je n'ai pas d'argent.", "I have no money.", ""), ("Kanino ito?", "À qui est-ce ?", "Whose is this?", "")],
 r"\b(may|mayroon|meron|wala|kanino|akin|iyo|kanya)\b", None),
pt('A2', 'gusto', ("Vouloir, pouvoir, devoir ; demander",
 "Ces mots ne se conjuguent pas : gusto (vouloir, aimer), ayaw (ne pas vouloir), kailangan (avoir besoin, falloir), puwede / pwede (pouvoir, être permis), dapat (devoir). Le sujet est à la forme ng / génitif et le verbe suit à l'infinitif, avec ligature : Gusto kong kumain. Ayaw niyang umalis. Kailangan mong mag-aral.\nDemande polie : paki- + racine (Pakisara ang pinto = fermez la porte, s'il vous plaît), ou Puwede po bang… ?"),
 ('Want, can, must; asking',
 "These words do not conjugate: gusto (want, like), ayaw (not want), kailangan (need, must), puwede / pwede (can, may), dapat (should). The person is in the ng / genitive form and the verb follows in the infinitive, with the linker: Gusto kong kumain. Ayaw niyang umalis. Kailangan mong mag-aral.\nPolite request: paki- + root (Pakisara ang pinto = please close the door), or Puwede po bang… ?"),
 [("Gusto kong matuto ng Tagalog.", "Je veux apprendre le tagalog.", "I want to learn Tagalog.", ""), ("Pakiulit po.", "Répétez, s'il vous plaît.", "Please repeat.", "")],
 r"\b(gusto|ayaw|kailangan|puwede|pwede|dapat)\b", ['gusto', 'ayaw', 'kailangan', 'puwede', 'dapat']),
pt('B1', 'maka', ("Pouvoir faire et faire sans le vouloir : maka-, ma-",
 "maka- / makapag- expriment la capacité ou le fait d'avoir réussi à faire : makakain (pouvoir manger), nakakain ako (j'ai pu manger), nakapagluto siya (elle a réussi à cuisiner).\nma- + racine (focus objet) exprime une perception ou un acte involontaire : nakita (vu), narinig (entendu), nalaman (appris, su), nasira (cassé).\nLes aspects suivent le même modèle que les autres verbes : nakita (accompli), nakikita (inaccompli), makikita (à venir)."),
 ('Being able and doing involuntarily: maka-, ma-',
 "maka- / makapag- express ability or managing to do something: makakain (be able to eat), nakakain ako (I managed to eat), nakapagluto siya (she managed to cook).\nma- + root (object focus) expresses perception or an involuntary act: nakita (seen), narinig (heard), nalaman (found out), nasira (broken).\nAspects follow the usual pattern: nakita (completed), nakikita (incompleted), makikita (contemplated)."),
 [("Nakita ko siya kahapon.", "Je l'ai vu hier.", "I saw him yesterday.", ""), ("Hindi ako makatulog.", "Je n'arrive pas à dormir.", "I can't sleep.", "")],
 r"\b(nakita|narinig|nalaman|nasira|makakain|makatulog|nakapag\w+|makapunta)\b", None),
]
